{"code":"import os, time
def list_skills(p="/opt/hermes/skills"):
    dirs = sorted([d for d in os.listdir(p) if os.path.isdir(os.path.join(p,d)) and not d.startswith('.')])
    for d in dirs[:4]:
        m = os.path.join(p,d,"SKILL.md")
        if os.path.exists(m):
            s = os.stat(m)
            print(f"{d}: SKILL.md mtime={time.strftime('%Y-%m-%d %H:%M', time.gmtime(s.st_mtime))}, size={s.st_size}")
            # first non-empty non-header line
            with open(m) as f:
                for line in f:
                    line=line.strip()
                    if line and not line.startswith('#') and not line.startswith('---'):
                        print(f"     -> {line[:90]}")
                        break
    print(f"... total dirs (excl .): {len(dirs)}")
list_skills()
